#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

#define int long long
const int mod1 = 998244353, mod2 = 1e9 + 7;
const int pw[] = {1, 10, 100, 1000, 10000, 100000, 1000000};

int s[7], answer, count1, total, count2;
vector<int> v[7];

void generate_sequences(int level, int value) {
    if (level == 7) return;
    v[level].push_back((count1 - value + mod1) % mod1);
    s[level] += (count1 - value + mod1) % mod1;
    count1++;
    for (int digit = 0; digit <= 9; ++digit) {
        generate_sequences(level + 1, value * 10 + digit);
    }
}

bool is_valid(int x) {
    return x * pw[6] + 999999 <= total && x * pw[6] * 10 > total;
}

void explore(int level, int current) {
    if (current > total) return;
    if (is_valid(current)) {
        for (int i = 0; i <= 6; ++i) {
            int p = ((count2 + 1 - (current * pw[i])) % mod1 + mod1) % mod1;
            int w = (int)(lower_bound(v[i].begin(), v[i].end(), mod1 - p) - v[i].begin());
            answer = (answer + (s[i] + p * v[i].size() - mod1 * (v[i].size() - w))) % mod2;
        }
        count2 += count1;
        return;
    }
    count2++;
    answer = (answer + ((count2 - current) % mod1 + mod1) % mod1) % mod2;
    for (int i = (level == 0 ? 1 : 0); i <= 9; ++i) {
        explore(level + 1, current * 10 + i);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> total;
    generate_sequences(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(v[i].begin(), v[i].end());
    }
    count2 = -1;
    explore(0, 0);
    cout << answer << '\n';
    return 0;
}
